package com.onebytelabs.zlplay;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import com.onebytelabs.zlplay.remote.RemoteClient;import org.json.*;
/** Foreground remote mode: no AudioSession, decoder, audio files or local playback engine. */
public final class RemoteActivity extends Activity {
 private final java.util.concurrent.ExecutorService setup=java.util.concurrent.Executors.newSingleThreadExecutor();private RemoteClient client;private WebView web;private AlertDialog exitConfirmation;private boolean destroyed;private String address,code;private Button connect;private TextView status;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView label(int id,int size){TextView v=new TextView(this);v.setText(id);v.setTextColor(0xffecf1fa);v.setTextSize(size);return v;}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(Build.VERSION.SDK_INT>=30){getWindow().getDecorView().setWindowInsetsAnimationCallback(null);android.view.WindowInsetsController controller=getWindow().getInsetsController();if(controller!=null)controller.hide(WindowInsets.Type.systemBars());}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::confirmExit);showConnection();String invitation=getIntent().getStringExtra("invitation");if(invitation!=null)connectInvitation(invitation);}
 private void showConnection(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER);root.setPadding(dp(32),dp(16),dp(32),dp(16));root.setBackgroundColor(0xff0b121d);root.addView(label(R.string.remote_mode,28));root.addView(label(R.string.remote_connect_help,16));status=label(R.string.remote_no_audio,13);status.setPadding(0,dp(18),0,dp(12));root.addView(status);connect=new Button(this);connect.setText(R.string.remote_scan);root.addView(connect,new LinearLayout.LayoutParams(dp(300),dp(64)));connect.setOnClickListener(v->startActivityForResult(new Intent(this,QrScanActivity.class),12));setContentView(root);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=12||result!=RESULT_OK||data==null)return;connectInvitation(data.getStringExtra("invitation"));}
 private void connectInvitation(String text){final com.onebytelabs.zlplay.remote.QrInvitation invite;try{invite=com.onebytelabs.zlplay.remote.QrInvitation.parse(text);}catch(Exception e){status.setText(R.string.remote_bad_qr);return;}connect.setEnabled(false);status.setText(R.string.remote_connecting);setup.execute(()->{for(String host:invite.hosts){try{String cert=RemoteClient.probe(host);if(!cert.equals(invite.certificate))continue;address=host;code=invite.key;runOnUiThread(()->{if(!destroyed)pair(invite.certificate);});return;}catch(Exception ignored){}}runOnUiThread(()->{if(!destroyed){status.setText(R.string.remote_connect_error);connect.setEnabled(true);}});});}
 private void pair(String certificate){status.setText(R.string.remote_connecting);var prefs=getSharedPreferences("remote",0);String device=prefs.getString("device",null);if(device==null){device=java.util.UUID.randomUUID().toString();prefs.edit().putString("device",device).apply();}client=new RemoteClient(address,device,new RemoteClient.Listener(){public void state(JSONObject state){runOnUiThread(()->{if(web!=null&&!destroyed)web.evaluateJavascript("window.acceptState&&window.acceptState("+state.toString()+")",null);});}public void disconnected(){runOnUiThread(()->{if(web!=null&&!destroyed)web.evaluateJavascript("window.remoteDisconnected&&window.remoteDisconnected()",null);});}});client.pair(code,certificate,()->runOnUiThread(()->{if(!destroyed){prefs.edit().putString("address",address).apply();showRemote();}}),failure->runOnUiThread(()->{if(!destroyed){client.close();status.setText(R.string.remote_connect_error);connect.setEnabled(true);}}));code=null;}
 private void showRemote(){web=new WebView(this);web.setBackgroundColor(0xff0b121d);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setDomStorageEnabled(false);web.getSettings().setSupportMultipleWindows(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Object(){@JavascriptInterface public void send(String message){try{if(client!=null)client.send(new JSONObject(message));}catch(JSONException ignored){}}@JavascriptInterface public void exit(){runOnUiThread(()->confirmExit());}},"ZLRemote");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return true;}});setContentView(web);web.loadUrl("file:///android_asset/remote.html");}
 private void confirmExit(){if(web==null){finish();return;}if(exitConfirmation!=null&&exitConfirmation.isShowing())return;exitConfirmation=new AlertDialog.Builder(this).setTitle(R.string.remote_exit_title).setMessage(R.string.remote_exit_help).setNegativeButton(android.R.string.cancel,(d,w)->{}).setPositiveButton(R.string.remote_exit_confirm,(d,w)->finish()).show();}
 @android.annotation.SuppressLint("GestureBackNavigation") // API 33+ uses OnBackInvokedDispatcher above; keep the legacy path for API 26–32.
 @Override public void onBackPressed(){confirmExit();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused&&Build.VERSION.SDK_INT>=30&&getWindow().getInsetsController()!=null){getWindow().getInsetsController().hide(WindowInsets.Type.systemBars());getWindow().getInsetsController().setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}
 @Override protected void onDestroy(){destroyed=true;if(client!=null)client.close();setup.shutdownNow();if(web!=null){web.removeJavascriptInterface("ZLRemote");web.destroy();}super.onDestroy();}
}
